#define ABS(x) ((x) < 0 ? -(x) : (x))
static inline int approx_dist(int dx, int dz)
{
    dx = abs(dx);
    dz = abs(dz);
    if (dz < dx)
        return dx + dz / 2;
    return dz + dx / 2;
}
int func_00063E54(PURSUER *cop, unsigned char *p)
{
    int x1, z1, x2, z2;
    int dx, dz;
    int rdx, rdz;
    int n;
    int d;
    int ang;
    int cang;
    int diff;
    int steps;
    int speed, carspeed;
    int cdx, cdz, kdx, kdz;
    CAR_DATA *car;
    int cid;

    x1 = cop->x;
    z1 = cop->z;
    car = &D_0009B230[p[0]];
    x2 = car->pos.vx;
    z2 = car->pos.vz;
    rdx = x2 - x1;
    rdz = z2 - z1;
    d = approx_dist(rdx, rdz);
    if (d >= 15000)
        return 0;
    if (p[5] != 0) {
        PURSUER *c = &D_000C4690[p[5]];
        if (c->f798 == 1)
            return 1;
        ang = ratan2(rdx, rdz) & 0xFFF;
        if (ABS(((ang - cop->ang + 0x800) & 0xFFF) - 0x800) < 0x400) {
            ang = car->direction;
            speed = cop->speed;
            cang = cop->ang;
            carspeed = car->speed;
            steps = 0;
            if (speed != 0)
                steps = d / speed;
            if (steps < 4) {
                cdx = (speed * rcossin_tbl[(cang & 0xFFF) * 2]) >> 12;
                cdz = (speed * rcossin_tbl[(cang & 0xFFF) * 2 + 1]) >> 12;
                kdx = (carspeed * rcossin_tbl[(ang & 0xFFF) * 2]) >> 12;
                kdz = (carspeed * rcossin_tbl[(ang & 0xFFF) * 2 + 1]) >> 12;
            } else {
                steps = steps / 4;
                cdx = (speed * rcossin_tbl[(cang & 0xFFF) * 2]) >> 10;
                cdz = (speed * rcossin_tbl[(cang & 0xFFF) * 2 + 1]) >> 10;
                kdx = (carspeed * rcossin_tbl[(ang & 0xFFF) * 2]) >> 10;
                kdz = (carspeed * rcossin_tbl[(ang & 0xFFF) * 2 + 1]) >> 10;
            }
            if (steps > 20)
                steps = 20;
            while (steps != 0) {
                x1 += cdx;
                z1 += cdz;
                x2 += kdx;
                z2 += kdz;
                rdx = ABS(x1 - x2);
                rdz = ABS(z1 - z2);
                if (rdz < rdx)
                    d = rdx + rdz / 2;
                else
                    d = rdz + rdx / 2;
                if (d < 1200)
                    goto hit;
                steps--;
            }
        }
        return 0;
hit:
        cop->timer3C = 10;

    }
    return 1;
}
